pcaBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "pcaBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "AnalisiMercato",
                name = "pca",
                version = c(2,0,9),
                options = options,
                results = pcaResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'none')
        }))

#' Analisi delle Componenti Principali
#'
#' 
#' @param data .
#' @param vars Variabili quantitative usate per costruire le componenti
#'   principali. Devono essere almeno due. La PCA opera sulla matrice di
#'   covarianza (se non standardizzate) o di correlazione (se standardizzate).
#' @param supp_quant Variabili quantitative che NON contribuiscono al calcolo
#'   delle componenti, ma vengono proiettate a posteriori nel piano principale.
#'   Utili per validare le componenti con variabili esterne.
#' @param supp_qual Variabile categoriale che NON contribuisce al calcolo
#'   delle componenti. Usata SOLO per colorare le osservazioni nel biplot.
#' @param supp_qual_map Una o più variabili categoriali supplementari. I
#'   baricentri delle loro modalità vengono proiettati nel piano principale e
#'   disegnati nel grafico "Mappa di posizionamento".
#' @param id_var Variabile usata per etichettare le osservazioni nelle tabelle
#'   e nel biplot.
#' @param tuto .
#' @param standardize Se TRUE applica la PCA sulla matrice di correlazione
#'   (z-score preventivo). Raccomandato quando le variabili hanno unità di
#'   misura o varianze diverse. Se FALSE applica la PCA sulla matrice di
#'   covarianza.
#' @param ncp Numero di componenti principali da ritenere (massimo 5). Per
#'   orientarsi sulla scelta, consultare la tabella degli autovalori e lo scree
#'   plot (criterio di Kaiser: λ > 1; criterio del gomito; criterio della
#'   varianza cumulata).
#' @param rotation Rotazione applicata ai loadings per facilitare
#'   l'interpretazione delle componenti. Varimax (ortogonale) massimizza la
#'   varianza dei loadings al quadrato per ciascuna componente; Promax (obliqua)
#'   consente che le componenti ruotate siano correlate.
#' @param show_ind .
#' @param top_ind .
#' @param axis_x Componente da visualizzare sull'asse orizzontale del cerchio
#'   delle correlazioni e del biplot (es. 1 = PC1).
#' @param axis_y Componente da visualizzare sull'asse verticale del cerchio
#'   delle correlazioni e del biplot (es. 2 = PC2).
#' @param plot_scree .
#' @param plot_circle .
#' @param plot_biplot .
#' @param plot_cos2 .
#' @param plot_map Plot delle sole variabili: baricentri delle modalità della
#'   variabile qualitativa supplementare + (opzionalmente) vettori delle attive
#'   e/o delle quantitative supplementari. Utile per leggere il posizionamento
#'   di segmenti o marche rispetto agli attributi.
#' @param map_show_active Se TRUE aggiunge le frecce delle variabili attive
#'   alla mappa.
#' @param map_show_supp_quant Se TRUE aggiunge le frecce delle variabili
#'   quantitative supplementari (se presenti) alla mappa.
#' @param map_width .
#' @param map_height .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$settings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$eigenvalues} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ss_loadings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$phi} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$var_coord} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$var_contrib} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$var_cos2} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ind_group$ind_coord} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ind_group$ind_contrib} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ind_group$ind_cos2} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot_scree} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_circle} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_biplot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_cos2} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_map} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$out_PC1} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$out_PC2} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$out_PC3} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$out_PC4} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$out_PC5} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$settings$asDF}
#'
#' \code{as.data.frame(results$settings)}
#'
#' @export
pca <- function(
    data,
    vars,
    supp_quant,
    supp_qual,
    supp_qual_map,
    id_var,
    tuto = TRUE,
    standardize = TRUE,
    ncp = 2,
    rotation = "none",
    show_ind = FALSE,
    top_ind = 20,
    axis_x = 1,
    axis_y = 2,
    plot_scree = TRUE,
    plot_circle = TRUE,
    plot_biplot = TRUE,
    plot_cos2 = TRUE,
    plot_map = FALSE,
    map_show_active = FALSE,
    map_show_supp_quant = TRUE,
    map_width = 800,
    map_height = 650) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pca requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(supp_quant)) supp_quant <- jmvcore::resolveQuo(jmvcore::enquo(supp_quant))
    if ( ! missing(supp_qual)) supp_qual <- jmvcore::resolveQuo(jmvcore::enquo(supp_qual))
    if ( ! missing(supp_qual_map)) supp_qual_map <- jmvcore::resolveQuo(jmvcore::enquo(supp_qual_map))
    if ( ! missing(id_var)) id_var <- jmvcore::resolveQuo(jmvcore::enquo(id_var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(supp_quant), supp_quant, NULL),
            `if`( ! missing(supp_qual), supp_qual, NULL),
            `if`( ! missing(supp_qual_map), supp_qual_map, NULL),
            `if`( ! missing(id_var), id_var, NULL))

    for (v in supp_qual) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in supp_qual_map) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pcaOptions$new(
        vars = vars,
        supp_quant = supp_quant,
        supp_qual = supp_qual,
        supp_qual_map = supp_qual_map,
        id_var = id_var,
        tuto = tuto,
        standardize = standardize,
        ncp = ncp,
        rotation = rotation,
        show_ind = show_ind,
        top_ind = top_ind,
        axis_x = axis_x,
        axis_y = axis_y,
        plot_scree = plot_scree,
        plot_circle = plot_circle,
        plot_biplot = plot_biplot,
        plot_cos2 = plot_cos2,
        plot_map = plot_map,
        map_show_active = map_show_active,
        map_show_supp_quant = map_show_supp_quant,
        map_width = map_width,
        map_height = map_height)

    analysis <- pcaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

